<?php
declare(strict_types=1);require_once __DIR__.'/includes/functions.php';require_login();if($_SERVER['REQUEST_METHOD']!=='POST')redirect('browse.php');verify_csrf();$rid=(int)($_POST['recipe_id']??0);$body=trim($_POST['body']??'');if(mb_strlen($body)<2||mb_strlen($body)>1000){flash('error','Comment must be between 2 and 1000 characters.');redirect('recipe.php?id='.$rid);} $status=is_admin()?'approved':'approved';$stmt=db()->prepare('INSERT INTO comments(user_id,recipe_id,body,status) VALUES(?,?,?,?)');$stmt->execute([current_user()['id'],$rid,$body,$status]);$stmt=db()->prepare('SELECT author_id,title FROM recipes WHERE id=?');$stmt->execute([$rid]);$r=$stmt->fetch();if($r&&$r['author_id']!=current_user()['id'])notify((int)$r['author_id'],'comment',current_user()['display_name'].' commented on “'.$r['title'].'”.',url('recipe.php?id='.$rid));audit('COMMENT_RECIPE',$rid);flash('success','Comment posted.');redirect('recipe.php?id='.$rid.'#community');
